// VIRTUAL DESTRUCTOR: PREVENTS SLICING/LEAKS

class Base {
public:
    // VIRTUAL ensures Derived's destructor is accessed via vtable lookup
    virtual ~Base() = default;
};

class Derived : public Base {
    int* resource;
public:
    Derived() : resource(new int[10]) {}
    ~Derived() { delete[] resource; /* Cleanup occurs */ }
};

